match(3, 'loss', 'xm2', 'Extinct animal and the region', ['A. Dodo', 'B. Quagga', 'C. Thylacine', 'D. Steller\'s sea cow'], ['p. Africa', 'q. Mauritius', 'r. Australia', 's. Russia'], 'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-r, B-p, C-q, D-s'], 'Dodo from Mauritius, quagga from Africa, thylacine from Australia and Steller\'s sea cow from Russia.');
match(3, 'loss', 'xm3', 'Alien species and the problem', ['A. Parthenium', 'B. Lantana camara', 'C. <i>Eichhornia</i>', 'D. <i>Clarias gariepinus</i>'], ['p. Carrot grass causing pollen allergy', 'q. Invasive terrestrial weed', 'r. Water hyacinth, aquatic weed', 's. African catfish that threatens native fishes'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'Parthenium is carrot grass, Lantana is a terrestrial weed, Eichhornia the water hyacinth and Clarias the catfish.');
pass('xp1', 'Passage: birds and latitude', 'A bird watcher compares the number of bird species at different latitudes. At 0° to 5° N, an area has about 1400 species. At 41° N an area of the same size has 105 species, and at 71° N only 56 species. She also notes that the climate near the equator is warm, humid and almost the same through the year.');
pq('xp1', 3, 'patterns', 'The pattern she found is called the', 'latitudinal gradient in species diversity', ['species-area relationship', 'rivet popper hypothesis', 'evil quartet'], 'Diversity falls from the equator to the poles.');
