pq('xp1', 4, 'patterns', 'The number of species at 41° N is about what fraction of that near the equator?', '7.5 per cent', ['75 per cent', '0.75 per cent', '50 per cent'], '105/1400 × 100 = 7.5 per cent.');
nat(3, 'patterns', 'Colombia has 1400 bird species and New York has 105. How many times is the number in Colombia that of New York? Give the answer to one decimal.', 13.3, '1400/105 = 13.33, about 13.3.', null, null, 0.05);
